DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.create_civic_report(jsonb,text)'::regprocedure) INTO definition; definition:=replace(definition,'INSERT INTO public.issue_secrets(issue_id,recovery_token) VALUES(new_id,_token);','INSERT INTO public.issue_secrets(issue_id,recovery_token) VALUES(new_id,_token); IF _report->>''original_path'' IS NOT NULL THEN INSERT INTO public.issue_photos(issue_id,original_path,display_path,source,metadata,original_sha256) VALUES(new_id,_report->>''original_path'',_report->>''display_path'',coalesce(_report->>''photo_source'',''gallery''),coalesce(_report->''photo_metadata'',''{}''::jsonb),_report->>''original_sha256''); END IF;'); EXECUTE definition; END $$;
CREATE TABLE public.issue_ownership_reviews(issue_id uuid PRIMARY KEY REFERENCES public.issues(id),state text NOT NULL DEFAULT 'pending',reason text NOT NULL DEFAULT 'Asset ownership requires review',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.issue_ownership_reviews TO authenticated;
GRANT ALL ON public.issue_ownership_reviews TO service_role;
ALTER TABLE public.issue_ownership_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "staff ownership reviews" ON public.issue_ownership_reviews FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
CREATE OR REPLACE FUNCTION public.prepare_case_review() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE candidate uuid; BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.issue_ownership_reviews(issue_id) VALUES(NEW.id); END IF; IF NEW.duplicate_candidate_id IS NULL AND NEW.category<>'other' AND NEW.duplicate_of IS NULL THEN SELECT i.id INTO candidate FROM public.issues i WHERE i.id<>NEW.id AND i.duplicate_of IS NULL AND i.category=NEW.category AND i.status NOT IN ('resolved','closed','rejected') AND 6371000*2*asin(least(1.0,sqrt(power(sin(radians(i.lat-NEW.lat)/2),2)+cos(radians(NEW.lat))*cos(radians(i.lat))*power(sin(radians(i.lng-NEW.lng)/2),2))))<=120 AND (SELECT count(*) FROM (SELECT DISTINCT lower(t) AS word FROM regexp_split_to_table(NEW.title||' '||coalesce(NEW.summary,''),'[^[:alnum:]]+') t WHERE length(t)>=4) a JOIN (SELECT DISTINCT lower(t) AS word FROM regexp_split_to_table(i.title||' '||coalesce(i.summary,''),'[^[:alnum:]]+') t WHERE length(t)>=4) b USING(word))>=2 ORDER BY i.created_at LIMIT 1; IF candidate IS NOT NULL THEN UPDATE public.issues SET duplicate_candidate_id=candidate WHERE id=NEW.id; INSERT INTO public.issue_events(issue_id,kind,actor_label,note) VALUES(NEW.id,'duplicate_candidate','CivicFix review','Nearby category and description evidence flagged; staff must review, not a confirmed match.'); END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER prepare_case_review AFTER INSERT ON public.issues FOR EACH ROW EXECUTE FUNCTION public.prepare_case_review();
CREATE OR REPLACE FUNCTION public.finish_ownership_review() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.authority_id IS NOT NULL THEN UPDATE public.issue_ownership_reviews SET state='assigned' WHERE issue_id=NEW.id; END IF; RETURN NEW; END $$;
CREATE TRIGGER finish_ownership_review AFTER UPDATE OF authority_id ON public.issues FOR EACH ROW EXECUTE FUNCTION public.finish_ownership_review();